class Solution:
    def maxScore(self, nums: List[int]) -> int:
        n = len(nums)
        best = float('-inf')
        for i in range(n - 1):
            p = sum(nums[:i + 1])
            m = min(nums[i + 1:])
            best = max(best, p - m)
        return best

