class Solution {
public:
    long long maxScore(vector<int>& nums) {
        int n = nums.size();
        long long best = LLONG_MIN;
        for (int i = 0; i < n - 1; i++) {
            long long p = 0;
            for (int j = 0; j <= i; j++) p += nums[j];
            int m = INT_MAX;
            for (int j = i + 1; j < n; j++) m = min(m, nums[j]);
            best = max(best, p - m);
        }
        return best;
    }
};

