        n = len(nums)
        sufMin = [0] * n
        sufMin[n - 1] = nums[n - 1]
        for i in range(n - 2, -1, -1):
            sufMin[i] = min(nums[i], sufMin[i + 1])
        p = 0
        best = float('-inf')
        for i in range(n - 1):
            p += nums[i]
            best = max(best, p - sufMin[i + 1])
        return best

